import { afterEach, describe, it, expect, vi } from "vitest";
import { safeLog, safeSdkLogger, safeWorkerError } from "@/lib/observability";
const owner = "11111111-1111-4111-8111-111111111111";
const secrets = {
  message: "private-body",
  token: "private-token",
  email: "[REDACTED_EMAIL]",
  headers: { Authorization: "Bearer private-token" },
  payload: { subject: "private-subject" },
  cause: new Error("private-provider-body"),
};
afterEach(() => vi.restoreAllMocks());
describe("enforced structured log boundary", () => {
  it("captures all levels and discards unknown fields recursively", () => {
    for (const level of ["debug", "info", "warn", "error"] as const) {
      const spy = vi.spyOn(console, level).mockImplementation(() => {});
      safeLog(level, "usage", {
        code: "WORKER_FAILED",
        userId: owner,
        ...secrets,
      });
      expect(JSON.parse(spy.mock.calls[0][0])).toEqual({
        event: "usage",
        code: "WORKER_FAILED",
        userId: owner,
      });
      for (const input of [
        secrets,
        { code: "private-token", userId: owner },
        { code: "WORKER_FAILED", userId: "[REDACTED_EMAIL]" },
        { code: "WORKER_FAILED", userId: secrets },
      ])
        safeLog(level, "usage", input);
      expect(spy).toHaveBeenCalledTimes(1);
      Reflect.apply(safeSdkLogger[level], null, [
        secrets,
        new Error("private-provider-body"),
      ]);
      expect(JSON.stringify(spy.mock.calls)).not.toMatch(/private-|recipient@/);
    }
  });
  it("normalizes thrown telemetry without a cause or original stack", () => {
    const error = safeWorkerError();
    expect(error.message).toBe("WORKER_FAILURE");
    expect(error.stack).toBe("Error: WORKER_FAILURE");
    expect(error.cause).toBeUndefined();
  });
});
it("scrubs step and function errors before Inngest can persist failure telemetry", async () => {
  const { SafeTelemetry, inngest } = await import("@/lib/inngest-client");
  const middleware = new SafeTelemetry({ client: inngest });
  const next = async () => {
    throw Object.assign(
      new Error("private-token [REDACTED_EMAIL] private-body"),
      { cause: secrets, config: secrets },
    );
  };
  for (const invoke of [
    () => middleware.wrapStepHandler({ next } as never),
    () => middleware.wrapFunctionHandler({ next } as never),
  ]) {
    try {
      await invoke();
      throw new Error("must throw");
    } catch (error) {
      expect(error).toBeInstanceOf(Error);
      expect((error as Error).message).toBe("WORKER_FAILURE");
      expect(JSON.stringify(error)).not.toMatch(/private-|recipient@/);
      expect((error as Error).stack).toBe("Error: WORKER_FAILURE");
    }
  }
});
